param([Parameter(Mandatory)][string]$RequestPath)
$ErrorActionPreference='Stop';Import-Module (Join-Path $PSScriptRoot 'Repato.QaAddinDeployment.psm1') -Force;Import-Module (Join-Path $PSScriptRoot 'Repato.CandidateEvidence.psm1') -Force
$r=Get-Content $RequestPath -Raw|ConvertFrom-Json
if($r.candidateEvidence){
    if(!$r.taskId -or !$r.workflowId){throw 'Generic deployment-validation request is missing canonical identity.'}
    $e=$r.candidateEvidence;$root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..\DeploymentCandidates\AgentBuilds'));$runnerRoot=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..\QA'))
    $null=Resolve-RepatoCandidateEvidence -Evidence $e -AuthenticatedEvidence $e -ApprovedCandidateRoot $root -ApprovedRunnerManifestRoot $runnerRoot -TaskId $r.taskId -WorkflowId $r.workflowId -QaWorkflowId $r.qaWorkflowId -TestId $r.testId
    $x=Test-TaraFrozenCandidateQaIsolation -CandidateDirectory $e.candidateDirectory -ExpectedArtifactSha256 $e.candidateDllSha256 -ExpectedSourceCommit $e.candidateSourceCommit -QaWorkflowId $e.qaWorkflowId -TestId $e.testId;$qaRoot=Split-Path $x.InstalledDllPath;$manifestRoot=Split-Path $qaRoot -Parent;$runnerPath=[IO.Path]::GetFullPath((Join-Path $manifestRoot ([IO.Path]::GetFileName($e.runnerManifestPath))))
    if(!(Test-Path -LiteralPath $runnerPath -PathType Leaf) -or (Get-FileHash -LiteralPath $runnerPath -Algorithm SHA256).Hash -ine $e.runnerManifestSha256){throw 'Deployed runner manifest does not match authenticated source evidence.'}
    [pscustomobject]@{schemaVersion=1;operation=$r.operation;requestId=$r.requestId;succeeded=[bool]$x.Success;candidateCommit=$e.candidateSourceCommit;candidateSha256=$x.CandidateSha256;qaWorkflowId=$e.qaWorkflowId;testId=$e.testId;validationIdentity=[Security.Principal.WindowsIdentity]::GetCurrent().Name;qaAddinRoot=$qaRoot;runnerManifestPath=$runnerPath;runnerManifestSha256=$e.runnerManifestSha256;isolationPassed=[bool]$x.Isolation.Allowed;manifestIntegrityPassed=$true;errorCode=$null;errorMessage=$null}|ConvertTo-Json -Compress;exit 0
}
if($r.schemaVersion -ne 1 -or $r.operation -cne 'validate-qa-deployment' -or $r.candidateCommit -cne 'fcf624ee3ed1c84fcc2bb78e4bf46d92090b98f3' -or $r.expectedCandidateSha256 -cne '7EC1C819C771DCE4EC4ADCADB93B0245D243F6675EC0F0B070B03303B1F412C2' -or $r.qaWorkflowId -cne 'create-plan-views-v1' -or $r.testId -cne $r.qaWorkflowId){throw 'Invalid fixed deployment-validation request.'}
$candidate='C:\Repato-Autonomous\Source\DeploymentCandidates\AgentBuilds\ReleaseCandidate-fcf624ee3ed1';$x=Test-TaraFrozenCandidateQaIsolation -CandidateDirectory $candidate -ExpectedArtifactSha256 $r.expectedCandidateSha256 -ExpectedSourceCommit $r.candidateCommit -QaWorkflowId $r.qaWorkflowId -TestId $r.testId;$qaRoot=Split-Path $x.InstalledDllPath;$manifestRoot=Split-Path $qaRoot -Parent;$runnerName='Repato.CreatePlanViews.TestRunner.addin';$runnerPath=Join-Path $manifestRoot $runnerName
[pscustomobject]@{schemaVersion=1;operation=$r.operation;requestId=$r.requestId;succeeded=[bool]$x.Success;candidateCommit=$r.candidateCommit;candidateSha256=$x.CandidateSha256;qaWorkflowId=$r.qaWorkflowId;testId=$r.testId;validationIdentity=[Security.Principal.WindowsIdentity]::GetCurrent().Name;qaAddinRoot=$qaRoot;runnerManifestPath=$runnerPath;runnerManifestSha256=$(if(Test-Path -LiteralPath $runnerPath -PathType Leaf){(Get-FileHash -LiteralPath $runnerPath -Algorithm SHA256).Hash}else{$null});isolationPassed=[bool]$x.Isolation.Allowed;manifestIntegrityPassed=[bool]($x.Success -and $x.Isolation.Allowed);errorCode=$null;errorMessage=$null}|ConvertTo-Json -Compress
